; Evaluate each form through MCP JVM mode on lab-run-inspection.
(require 'seon.operator.runtime 'datahike.api 'seon.db 'seon.cluster 'clojure.string)
(let [store (:seon.store/store (get @seon.operator.runtime/running-instances "lab-run-inspection")) db (datahike.api/branch-as-db (:seon.store/connection-object store) :current-src)] (try (let [row (seon.db/pull db '[:seon.fn/source :seon.fn/doc] [:seon.fn/sym "seon.render.transcript/render-run-ai"]) artifact (#'seon.cluster/read-source-artifact "/Users/sean/src/seon/data/clusters") snapshot (seon.cluster/source-snapshot)] {:head (seon.db/commit-id db) :doc (:seon.fn/doc row) :marker? (clojure.string/includes? (:seon.fn/source row) "EDIT-HOOK-PROBE-0906") :artifact-matches-files? (= (:seon.source/digest artifact) (:seon.source/digest snapshot)) :artifact-head (:seon.source/commit-id artifact)}) (finally (datahike.api/release-materialized-db db))))

(let [store (:seon.store/store (get @seon.operator.runtime/running-instances "lab-run-inspection")) conn (:seon.store/connection-object store) source (datahike.api/branch-as-db conn :current-src) fork (datahike.api/branch-as-db conn :cluster-lab-hook-proof)] (try (let [pattern '[:seon.fn/source :seon.fn/doc] id [:seon.fn/sym "seon.render.transcript/render-run-ai"]] {:source-head (seon.db/commit-id source) :fork-head (seon.db/commit-id fork) :same-head? (= (seon.db/commit-id source) (seon.db/commit-id fork)) :same-function? (= (seon.db/pull source pattern id) (seon.db/pull fork pattern id))}) (finally (datahike.api/release-materialized-db source) (datahike.api/release-materialized-db fork))))
